fn exodus(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Exodus", 1, "A new Egyptian administrator forgot Joseph, saw Israel's population as a threat, and converted the immigrant branch into forced labor.", "Midwives refused the kill-order, Moses's generation survived hidden in plain sight, and oppression intensified whenever compassion disrupted Pharaoh's plan.");
    crate::chapter!(story, "Exodus", 2, "Moses was placed in a basket among the reeds, adopted by Pharaoh's household, and later exiled after defending a beaten Hebrew worker.", "In Midian he married Zipporah, tended sheep, and lived quietly until the Maintainer remembered the covenant and heard the people's groaning.");
    crate::chapter!(story, "Exodus", 3, "A bush burned without being consumed, and Moses encountered the Maintainer's presence in a place that became holy by attention.", "Moses received the mission to confront Pharaoh, asked for a name and credentials, and heard that presence itself would accompany the release.");
    crate::chapter!(story, "Exodus", 4, "Moses objected through every available error channel, so signs were assigned: a staff, a diseased hand, and water becoming blood.", "Aaron became the public interface, Zipporah repaired a dangerous covenant omission, and Moses returned toward Egypt carrying both fear and commission.");
    crate::chapter!(story, "Exodus", 5, "Moses and Aaron asked Pharaoh to release Israel for worship, but Pharaoh answered by removing straw while keeping the brick quota.", "The workers blamed the new messengers, and Moses brought the failure report back to the Maintainer rather than disguising the worsening metrics.");
    crate::chapter!(story, "Exodus", 6, "The Maintainer restated the covenant promises: rescue, relationship, land, and identity for a people too exhausted to process encouragement.", "Moses's genealogy anchored the mission in actual households, while his speech difficulty remained part of the calling rather than a hidden defect.");
    crate::chapter!(story, "Exodus", 7, "Moses and Aaron entered Pharaoh's court, and Aaron's staff became a serpent before the magicians reproduced the sign with inferior magic.", "The Nile turned unusable, beginning the plague sequence that would expose Pharaoh's hardened ownership claim over Israel.");
    crate::chapter!(story, "Exodus", 8, "Frogs, gnats, and flies invaded Egypt in successive failures, while Goshen received a distinct environment rather than a universal blast radius.", "Pharaoh repeatedly promised release, repeatedly hardened his heart, and repeatedly discovered that a temporary rollback is not repentance.");
    crate::chapter!(story, "Exodus", 9, "Livestock disease, boils, and destructive hail struck Egypt, with warnings offered so that anyone listening could move servants and animals to shelter.", "Pharaoh admitted fault for a moment, then reversed course after the hail stopped, showing how quickly a panic confession can expire.");
    crate::chapter!(story, "Exodus", 10, "Locusts consumed what the hail spared, and darkness covered Egypt while the Israelites retained light in their own region.", "Pharaoh tried to negotiate partial compliance, but Moses insisted that worship could not be reduced to a carefully limited export package.");
    crate::chapter!(story, "Exodus", 11, "The final plague was announced, with a distinction between Egyptian firstborn and Israelite households already forming in the warning log.", "Moses left Pharaoh's presence with the nation poised for departure, and the coming night carried the weight of every previous refusal.");
    crate::chapter!(story, "Exodus", 12, "Israel received the Passover protocol: a marked doorway, a hurried meal, and a memorial release that would teach future generations what rescue meant.", "Judgment passed through Egypt, Pharaoh finally expelled the people, and the departing crowd carried dough, bones, and an urgent new calendar.");
    crate::chapter!(story, "Exodus", 13, "The firstborn were dedicated, unleavened bread became a recurring memory, and Joseph's bones traveled with the people as promised.", "A cloud by day and fire by night supplied the route, proving that liberation still needs navigation and visible guidance.");
    crate::chapter!(story, "Exodus", 14, "Pharaoh pursued the fleeing people to the sea, trapping them between military power and an apparently impossible boundary.", "Moses raised his staff, the waters opened, Israel crossed, and the pursuing army's process ended when the sea reclaimed the roadway.");
    crate::chapter!(story, "Exodus", 15, "Moses and Israel sang a victory song about the sea, the horse, the rider, and the Maintainer's steadfast reign.", "At Marah the water was bitter, so a tree became the appointed patch; the people learned that rescue includes ongoing provisioning.");
    crate::chapter!(story, "Exodus", 16, "Hunger in the wilderness produced complaints, and the Maintainer answered with bread-like manna each morning and quail at evening.", "Hoarding corrupted the allocation, while Sabbath required trust that tomorrow's portion would arrive without frantic overnight collection.");
    crate::chapter!(story, "Exodus", 17, "At Rephidim the people demanded water, and Moses struck the rock so a dry camp could drink from an unexpected source.", "Amalek attacked, and Israel prevailed while Moses's raised hands were supported by Aaron and Hur in an early lesson about shared endurance.");
    crate::chapter!(story, "Exodus", 18, "Jethro reunited Moses with Zipporah and their sons, then watched Moses personally process every dispute in the entire nation.", "He advised a tiered leadership structure, preserving Moses from administrative exhaustion and turning justice into a more sustainable service.");
    crate::chapter!(story, "Exodus", 19, "Israel reached Sinai, where the people were invited into a covenant identity as a treasured kingdom and priestly nation.", "Boundaries were placed around the mountain, because approaching the Maintainer required both welcome and reverent limits.");
    crate::chapter!(story, "Exodus", 20, "The covenant's central commands arrived as a direct interface: no rival gods, no corrupt images, no misuse of the divine name.", "Sabbath, parents, life, marriage, property, and truth received protection, while the people trembled at the voice and kept their distance.");
    crate::chapter!(story, "Exodus", 21, "Case law addressed servants, violence, injury, property damage, and the difficult question of how communal justice handles accidental harm.", "The commands treated neighbors as accountable persons rather than disposable resources, even while operating inside an ancient household economy.");
    crate::chapter!(story, "Exodus", 22, "Theft, guardianship, lending, seduction, magic, and treatment of vulnerable residents received specific legal branches.", "The covenant required restitution and hospitality, especially toward foreigners, widows, and orphans whose protection could not depend on status.");
    crate::chapter!(story, "Exodus", 23, "Courts were warned against false testimony, crowd pressure, bribery, and favoritism, while sabbath rhythms extended to fields and working animals.", "Festivals marked harvest and rescue, and a guiding messenger promised to lead Israel toward the land without excusing disobedience.");
    crate::chapter!(story, "Exodus", 24, "Moses read the covenant aloud, the people agreed, and blood marked the ratification of a relationship more serious than a casual pull request.", "Moses, Aaron, Nadab, Abihu, and elders saw a sign of the divine presence, while Moses ascended farther into the cloud.");
    crate::chapter!(story, "Exodus", 25, "Instructions began for the ark, table, lampstand, and offerings, turning worship into a carefully specified shared workspace.", "The sanctuary would carry the covenant's witness, provide bread and light, and make presence tangible without reducing it to a local object.");
    crate::chapter!(story, "Exodus", 26, "Curtains, frames, clasps, and veils defined the tabernacle's architecture, with layers separating common access from the innermost holy space.", "The portable dwelling was precise enough to travel, yet symbolically ordered enough to teach that holiness is not improvised by mood.");
    crate::chapter!(story, "Exodus", 27, "The bronze altar, court, hangings, and entrance were specified, giving sacrifice and gathering a visible perimeter.", "Pure oil was assigned for the lamps, requiring the people to maintain a steady light even while the wider journey remained unsettled.");
    crate::chapter!(story, "Exodus", 28, "Aaron and his sons received priestly garments: names on stones, a breastpiece of judgment, a robe, and a gold plate of holy dedication.", "The clothing made the priest a living memory interface, carrying the tribes before the Maintainer whenever he entered the sanctuary.");
    crate::chapter!(story, "Exodus", 29, "The ordination process washed, clothed, anointed, and sacrificed for the priests, establishing a repeatable release ceremony.", "Daily offerings and sacred meals defined the altar's rhythm, so the sanctuary's service would not depend on occasional enthusiasm.");
    crate::chapter!(story, "Exodus", 30, "The incense altar, census ransom, bronze basin, anointing oil, and holy incense were assigned distinct materials and restricted uses.", "The chapter treated worship resources as consecrated dependencies, not generic variables available to every private experiment.");
    crate::chapter!(story, "Exodus", 31, "Bezalel and Oholiab were gifted with craftsmanship to build the sanctuary, proving that wisdom can arrive through skilled hands and design.", "Sabbath was reiterated as a covenant sign, and stone tablets carried the written testimony supplied by the Maintainer.");
    crate::chapter!(story, "Exodus", 32, "Waiting at the mountain became unbearable, so the people commissioned a golden calf and celebrated a polished substitute for presence.", "Moses confronted the breach, shattered the tablets, and interceded amid judgment, while the camp learned that a local idol cannot own the future.");
    crate::chapter!(story, "Exodus", 33, "The Maintainer threatened to withdraw accompanying presence, and Israel mourned because a destination without guidance was not enough.", "Moses asked for assurance, for favor, and to see the Maintainer's glory, receiving a protected glimpse rather than an uncontrolled data dump.");
    crate::chapter!(story, "Exodus", 34, "New stone tablets were prepared, and the covenant was renewed with warnings against rival worship and exploitative treaties.", "Moses returned from the mountain with a radiant face, so he wore a veil when speaking to the people and uncovered it before the Maintainer.");
    crate::chapter!(story, "Exodus", 35, "Sabbath came first, then the people were invited to contribute materials for the sanctuary from willing hearts rather than forced extraction.", "Skilled workers, including women spinning and craftspeople shaping metal and wood, transformed generosity into a communal build process.");
    crate::chapter!(story, "Exodus", 36, "Contributions exceeded the construction need, so the workers asked Moses to stop the incoming stream before generosity became clutter.", "Curtains, frames, clasps, and the inner veil were assembled according to the mountain specification, turning plans into a portable dwelling.");
    crate::chapter!(story, "Exodus", 37, "Bezalel built the ark, table, lampstand, and incense altar, using gold, acacia wood, and deliberate proportions for each sacred component.", "The objects were not decorative leftovers; they organized memory, provision, light, prayer, and the community's approach to presence.");
    crate::chapter!(story, "Exodus", 38, "The bronze altar, basin, court, and entrance were completed, and the chapter recorded the inventory of metals used in the work.", "Ithamar supervised the accounting, showing that beautiful worship still benefits from transparent ledgers and named responsibility.");
    crate::chapter!(story, "Exodus", 39, "The priests' garments were finished, including the ephod, breastpiece, robe, tunics, and holy diadem with the tribal names carried close.", "Moses inspected the completed work and blessed the builders because every component matched the received design.");
    crate::chapter!(story, "Exodus", 40, "The tabernacle was erected, furnished, and anointed on the first day of the new year, completing the wilderness deployment.", "A cloud covered the tent and glory filled it; whenever the cloud lifted Israel moved, and whenever it rested the people stayed.");
    Ok(())
}

fn leviticus(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Leviticus", 1, "The burnt offering established a whole-animal gift, with the worshiper bringing it near and the priests handling the altar sequence.", "The procedure made approach costly and intentional, turning devotion into a visible `Result` rather than a vague private sentiment.");
    crate::chapter!(story, "Leviticus", 2, "Grain offerings brought flour, oil, incense, and salt, with portions burned while the remainder supported the priestly household.", "Leaven and honey were excluded from the altar portion, while salt preserved the covenant flavor of a durable offering.");
    crate::chapter!(story, "Leviticus", 3, "The fellowship offering shared the animal's richest fat and blood rules while allowing a communal meal around the sacrifice.", "Peace was not merely an internal feeling; it became a table with boundaries, gratitude, and a properly handled sacred resource.");
    crate::chapter!(story, "Leviticus", 4, "Sin offerings addressed failures by priests, the whole assembly, leaders, and ordinary people, scaling the remedy to the responsible role.", "Unintentional error still affected the sanctuary, so cleansing was provided before hidden corruption could spread through the community.");
    crate::chapter!(story, "Leviticus", 5, "Specific cases of withheld testimony, ritual uncleanness, rash vows, and accidental misuse received confession and restitution paths.", "When a worshiper could not afford an animal, smaller offerings were accepted, showing that repair was not reserved for the wealthy.");
    crate::chapter!(story, "Leviticus", 6, "Restitution for theft or deceit came before the guilt offering, requiring the offender to repair a neighbor's loss with an added amount.", "Priests also received the altar's operating procedures: keep the fire burning, handle sacred leftovers carefully, and maintain clean boundaries.");
    crate::chapter!(story, "Leviticus", 7, "The guilt, peace, grain, and sin offerings were given their portions, timing rules, and priestly shares.", "Fat and blood remained protected dependencies, while fellowship meals had expiration windows so holiness would not be treated as indefinite storage.");
    crate::chapter!(story, "Leviticus", 8, "Moses washed, clothed, anointed, and ordained Aaron and his sons through a public ceremony of blood, oil, garments, and patient repetition.", "The priests stayed at the sanctuary entrance for seven days, completing their initialization before handling the community's sacred requests.");
    crate::chapter!(story, "Leviticus", 9, "On the eighth day Aaron brought offerings for himself and the people, then blessed the assembly from the newly commissioned altar.", "Fire came from the Maintainer's presence and consumed the offering, and the people shouted before bowing into worship.");
    crate::chapter!(story, "Leviticus", 10, "Nadab and Abihu offered unauthorized fire and died before the sanctuary, a severe warning against treating holy service as personal experimentation.", "Aaron's remaining sons received rules for mourning, sobriety, and distinguishing holy from common while the family carried its grief.");
    crate::chapter!(story, "Leviticus", 11, "Animals, fish, birds, and insects were classified by clean and unclean traits, turning meals into a daily discipline of discernment.", "Contact with carcasses transferred uncleanness, so pots, clothing, and bodies needed careful handling before returning to ordinary use.");
    crate::chapter!(story, "Leviticus", 12, "Childbirth introduced a period of ritual status and purification, with offerings adjusted according to the household's means.", "The chapter treated postpartum recovery as a real communal process, giving the mother a defined path back into sanctuary participation.");
    crate::chapter!(story, "Leviticus", 13, "Skin conditions, fabric discoloration, and house-like mold were inspected by priests who quarantined uncertain cases rather than guessing.", "The repeated closures and rechecks made holiness resemble careful incident response: isolate, observe, and only then restore.");
    crate::chapter!(story, "Leviticus", 14, "A healed skin condition required birds, cedar, scarlet, hyssop, washing, shaving, and offerings before the person rejoined the camp.", "Houses with mildew received inspection and possible demolition, proving that even buildings could carry a contamination report.");
    crate::chapter!(story, "Leviticus", 15, "Bodily discharges created temporary uncleanness for individuals and objects, with washing and waiting as the ordinary remediation.", "After the period ended, offerings completed restoration, teaching the camp that embodied life deserves patient and non-shaming procedures.");
    crate::chapter!(story, "Leviticus", 16, "The Day of Atonement established the year's central cleanup: Aaron entered the inner sanctuary with blood, incense, and careful restraint.", "One goat was offered and another carried the people's accumulated failures into the wilderness, while the whole community rested from ordinary work.");
    crate::chapter!(story, "Leviticus", 17, "Sacrificial animals had to be brought to the sanctuary, preventing private altars and hidden bloodshed from fracturing the covenant.", "Blood was reserved as life and assigned to the altar, while consuming it remained outside the permitted food interface.");
    crate::chapter!(story, "Leviticus", 18, "Israel received boundaries around sexual relationships, rejecting exploitative family arrangements and the practices of surrounding nations.", "The land itself was pictured as able to reject defilement, so private desire carried public consequences in the community's shared environment.");
    crate::chapter!(story, "Leviticus", 19, "Holiness became neighbor-facing: leave gleanings, pay workers on time, judge fairly, protect the vulnerable, and refuse revenge.", "The chapter joined worship to ordinary ethics, insisting that love of neighbor is a core trait rather than an optional plugin.");
    crate::chapter!(story, "Leviticus", 20, "Severe penalties addressed child sacrifice, occult practice, sexual violations, and other breaches that threatened the community's identity.", "Israel was called to remain distinct from the nations around it, not as a boast of superiority but as a guarded covenant assignment.");
    crate::chapter!(story, "Leviticus", 21, "Priests received stricter rules for mourning, marriage, bodily presentation, and sanctuary service because their role represented the holy interface.", "Physical limitations did not erase a priest's dignity or share of sacred food, but they did shape which altar tasks were assigned.");
    crate::chapter!(story, "Leviticus", 22, "Priests had to inspect themselves and the offerings, keeping uncleanness and accidental defects from entering the sacred meal system.", "The chapter required willing, sound gifts and forbade treating the holy name as a casual destination for leftovers.");
    crate::chapter!(story, "Leviticus", 23, "The appointed festivals scheduled rest, Passover, first harvest, weeks, trumpets, atonement, and booths across Israel's calendar.", "Time itself became liturgy, with work paused so the people could remember rescue, provision, repentance, and wilderness shelter.");
    crate::chapter!(story, "Leviticus", 24, "Pure oil kept the lamp burning, and bread was arranged before the Maintainer as a weekly sign of shared provision.", "A blasphemy case and a life-for-life legal principle showed that speech, injury, and property all belonged under accountable justice.");
    crate::chapter!(story, "Leviticus", 25, "Every seventh year the land rested, and after seven cycles a Jubilee returned land, released debts, and reset household economic burdens.", "The law declared that land and people ultimately belonged to the Maintainer, limiting permanent ownership claims over either.");
    crate::chapter!(story, "Leviticus", 26, "Obedience was promised rain, harvest, peace, and presence, while rebellion produced escalating warnings, famine, exile, and desolation.", "Yet confession could reopen the covenant memory, because judgment was not written as a final deletion of the ancestral promise.");
    crate::chapter!(story, "Leviticus", 27, "Vows involving people, animals, houses, fields, and tithes received valuation rules so devotion would not become a chaotic accounting dispute.", "Consecrated things could not be casually reclaimed, and the chapter closed by assigning the tenth as a maintained share.");
    Ok(())
}

