    crate::chapter!(story, "Numbers", 6, "The Nazirite vow separated a person for a season of devotion through abstaining from wine, hair cutting, and contact with the dead.", "Aaron's blessing then spoke peace, protection, grace, and presence over the people as a public release from the sanctuary.");
    crate::chapter!(story, "Numbers", 7, "Tribal leaders brought carts, oxen, and offerings for the dedication of the altar, each presenting the same generous package on a separate day.", "The repetition was not wasted boilerplate; it recorded every tribe's participation in the shared commissioning.");
    crate::chapter!(story, "Numbers", 8, "Aaron arranged the lamps, and the Levites were cleansed, presented, and assigned in place of Israel's firstborn.", "Their service began at twenty-five and shifted at fifty, giving sacred labor both a season of strength and a season of supported retirement.");
    crate::chapter!(story, "Numbers", 9, "Passover was observed in the wilderness, with a second opportunity for those made unclean or away on a journey.", "The cloud over the tabernacle controlled movement: Israel traveled when it lifted and camped when it rested, even if the schedule felt opaque.");
