    crate::chapter!(story, "Numbers", 33, "The journey from Egypt was logged stage by stage, preserving every camp from the departure at Rameses to the plains of Moab.", "Israel was told to drive out the land's inhabitants and remove their idols, because partial cleanup would become a persistent source of trouble.");
